# ==================================================================================================
# The front-door directives (textual: run everywhere)
# ==================================================================================================
def _fd_text() -> str:
    return _FD_CADDY.read_text(encoding="utf-8")


def _brace_match(text: str, open_at: int) -> str:
    i = text.index("{", open_at)
    depth = 0
    for j in range(i, len(text)):
        if text[j] == "{":
            depth += 1
        elif text[j] == "}":
            depth -= 1
            if depth == 0:
                return text[i:j + 1]
    raise AssertionError("unbalanced braces")


def _canonical_body(text: str) -> str:
    m = re.search(r"\{\$AUSMT_PUBLIC_NAME\} \{", text)
    assert m, "the canonical site block must exist"
    return _brace_match(text, text.index("{", m.end() - 1))[1:-1]


def _section(text: str) -> str:
    body = _canonical_body(text)
    o, c = body.index(_SECTION_OPEN), body.index(_SECTION_CLOSE)
    assert o < c
    return body[o:body.index("\n", c) + 1]


def _strip_section(text: str) -> str:
    out, dropping = [], False
    for line in text.splitlines(keepends=True):
        if _SECTION_OPEN in line:
            dropping = True
        if not dropping:
            out.append(line)
        if _SECTION_CLOSE in line:
            dropping = False
    return "".join(out)


def test_section_sits_in_the_canonical_block_above_the_deny():
    """The hand-off section is INSIDE the canonical site block, ABOVE the @nonpublic deny and BELOW
    the path-url contract whose map it chains off, and outside the legacy render markers (both
    renderings keep it). FAILS IF it moves anywhere that changes which handle wins."""
    text = _fd_text()
    body = _canonical_body(text)
    assert _SECTION_OPEN in body and _SECTION_CLOSE in body
    assert body.index("# ---- end path-url contract") < body.index(_SECTION_OPEN), (
        "the map keys off {ausmt_pathurl_rest}, so it belongs after that section")
    assert body.index(_SECTION_CLOSE) < body.index("@nonpublic path"), (
        "the hand-off handles must sit ABOVE the @nonpublic deny")
    legacy = text[text.index("# >>> legacy-redirect"):text.index("# <<< legacy-redirect")]
    assert _SECTION_OPEN not in legacy


def test_map_keys_off_the_query_stripped_uri_and_imports_the_committed_table():
    """The mechanism: the map reads {ausmt_pathurl_rest} (the raw URI up to the first '?', declared
    by the path-url section), imports the committed table at its mount path, and defaults to EMPTY.
    The query strip is what stops a decorated link riding onto an NCI URL. `default ""` is what 404s
    an unlisted path. FAILS IF the input becomes the full URI, the import moves, or the default
    grows a value."""
    section = _section(_fd_text())
    opener = "map {ausmt_pathurl_rest} {ausmt_ts_target} {"
    assert opener in section, "the map must key off the query-stripped remainder"
    block = _brace_match(section, section.rindex("{", section.index(opener),
                                                 section.index("\n", section.index(opener))))
    assert f"import {_MAP_MOUNT}" in block, f"the map must import {_MAP_MOUNT}"
    assert re.search(r'default\s+""', block), "an unlisted path must map to EMPTY, with no fallback"


def test_known_routes_redirect_302_to_the_one_canonical_archive_host():
    """@ts_known fires only on a non-empty map result and redirects 302 to the fileServer prefix the
    ENGINE declares (_stationcheck.TS_ACCESS_PREFIX), with the map value appended. The prefix is
    hard-coded in the directive on purpose: the redirect target is then structurally confined to that
    host, so no table line can ever aim a Location somewhere else. FAILS IF the host drifts from the
    engine's constant, the matcher stops testing for empty, or the status changes."""
    section = _section(_fd_text())
    assert '@ts_known expression {ausmt_ts_target} != ""' in section
    want = f"redir {stcheck.TS_ACCESS_PREFIX}{{ausmt_ts_target}} 302"
    assert want in section, f"the redirect must be exactly {want!r}"
    assert "permanent" not in section, (
        "a hand-off is temporary by design: the archive's own path is not an AusMT contract")


def test_unlisted_paths_404_and_nothing_in_the_section_proxies():
    """@ts_prefix 404s both slash forms of the namespace, and NEITHER handle proxies: the route is
    TERMINAL at the front door, so no /go/ts/ request reaches the box and the C47 wall-2 allowlist is
    untouched by construction. FAILS IF a slash form is dropped or a reverse_proxy appears."""
    section = _section(_fd_text())
    m = re.search(r"@ts_prefix path (.+)", section)
    assert m and m.group(1).split() == ["/go/ts", "/go/ts/*"], (
        f"the namespace must be refused in both slash forms, got {m and m.group(1)!r}")
    assert 'respond "not found" 404' in section
    assert "reverse_proxy" not in section, "a hand-off route must never reach the box"


def test_compose_and_installer_carry_the_table_into_the_config():
    """The table is part of the CONFIG: compose mounts it read-only at the import path, and the
    installer's validate step mounts it too (caddy validate FAILS on a missing import, which is the
    point). FAILS IF either mount is dropped - the edge would then refuse to start, or validate would
    pass on a config the container cannot load."""
    assert f"./ts-routes.map:{_MAP_MOUNT}:ro" in _COMPOSE.read_text(encoding="utf-8")
    install = _INSTALL.read_text(encoding="utf-8")
    assert f'"$HERE/ts-routes.map:{_MAP_MOUNT}:ro"' in install, (
        "the validate step must mount the table it imports")
    assert "ts-routes.map ]" in install and "will 404" in install, (
        "a missing table must degrade to an EMPTY table (every route 404s), not a failed deploy")


def test_doctor_carries_the_ts_routes_leg():
    """doctor.sh source pins: the leg hash-compares the container-mounted table against the repo
    copy, requires a 302 to the table's own NCI Location on an open route, requires a 404 on a route
    the table does not name, and skips cleanly on an unreachable edge. The behavioural proof is
    sh-driven in test_frontdoor_doctor_sh.py. FAILS IF any of the three facts is dropped."""
    src = _DOCTOR.read_text(encoding="utf-8")
    leg = src.split("check_ts_routes()")[1].split("check_tailscale()")[0]
    assert "sha256sum /etc/caddy/ts-routes.map" in leg, "the mounted table must be hash-compared"
    assert '"302"' in leg and stcheck.TS_ACCESS_PREFIX in leg, (
        "the open probe must require a 302 to the archive host")
    assert '"404"' in leg, "the unlisted probe must require a 404"
    assert "ts-routes: skipped" in leg, "an unreachable edge must skip cleanly, not FAIL"
    assert "check_ts_routes" in src.split("run_report()")[1], "the leg must run in the report"


def test_runbook_documents_the_route_step_and_the_rollback():
    """RUNBOOK pins: the operator can find how the table ships, that it goes out BEFORE the data (a
    station that stops being open has to lose its route first), and the one-line withdrawal. FAILS IF
    the published operating procedure loses any of them."""
    rb = _RUNBOOK.read_text(encoding="utf-8")
    assert "ts-routes.map" in rb, "the runbook must name the route table"
    assert "/go/ts/" in rb, "the runbook must name the route shape"
    assert "before the data" in rb.lower(), "the order rule must be stated where the operator reads it"
    assert "404" in rb and "gen_ts_routes.py" in rb, "the rollback and the regenerate must be findable"


# ==================================================================================================
# Runtime pins: a REAL Caddy over the shipped directives (CI class; textual pins stand in locally)
# ==================================================================================================
def _free_port() -> int:
    s = socket.socket()
    s.bind(("127.0.0.1", 0))
    p = s.getsockname()[1]
    s.close()
    return p


def _wait_port(port: int, timeout: float = 10.0) -> None:
    end = time.time() + timeout
    while time.time() < end:
        try:
            with socket.create_connection(("127.0.0.1", port), timeout=0.2):
                return
        except OSError:
            time.sleep(0.05)
    raise AssertionError(f"port {port} never came up")


def _hermetic(text: str, td: Path, listen_port: int, stub_port: int, mappath: Path) -> str:
    """The shipped composition on one local http port, with the map import repointed at the fixture
    table. Everything else - the matchers, the map, the redirect, the 404 - is the shipped text."""
    text = text.replace("{$AUSMT_PUBLIC_NAME} {", f"http://canonical.test:{listen_port} {{")
    text = text.replace("{$AUSMT_LEGACY_REDIRECT_NAME} {", f"http://legacy.test:{listen_port} {{")
    text = text.replace("{$AUSMT_PUBLIC_NAME}", "canonical.test")
    text = text.replace("{$AUSMT_BOX_READER_UPSTREAM}", f"127.0.0.1:{stub_port}")
    text = text.replace("{$AUSMT_ACME_EMAIL}", "test@example.org")
    text = re.sub(r"output file \S+", f"output file {(td / 'access.json').as_posix()}", text)
    text = text.replace("admin unix//run/caddy-admin.sock", "admin off")
    text = text.replace("admin off\n", "admin off\n\tauto_https off\n", 1)
    return text.replace(f"import {_MAP_MOUNT}", f"import {mappath.as_posix()}")


def _stub_cfg(port: int) -> str:
    return ("{\n\tadmin off\n\tauto_https off\n}\n"
            + f":{port} {{\n\trespond \"STUB {{http.request.uri}}\" 200\n}}\n")


def _run_caddy(cfg_text: str, td: Path, name: str) -> subprocess.Popen:
    cfgpath = td / f"{name}.caddy"
    cfgpath.write_text(cfg_text, encoding="utf-8")
    v = subprocess.run(["caddy", "validate", "--adapter", "caddyfile", "--config", str(cfgpath)],
                       capture_output=True, text=True)
    assert v.returncode == 0, f"composed {name} config invalid:\n{v.stdout}\n{v.stderr}"
    return subprocess.Popen(["caddy", "run", "--adapter", "caddyfile", "--config", str(cfgpath)],
                            stdout=subprocess.PIPE, stderr=subprocess.PIPE)


def _stop(proc: subprocess.Popen) -> None:
    proc.terminate()
    try:
        proc.wait(timeout=5)
    except subprocess.TimeoutExpired:
        proc.kill()


def _get(port: int, path: str, host: str = "canonical.test") -> tuple:
    """(status, location-or-None, body) without following redirects."""
    req = urllib.request.Request(f"http://127.0.0.1:{port}{path}", headers={"Host": host})

    class _NoRedirect(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, *a, **k):  # noqa: ARG002
            return None

    try:
        r = urllib.request.build_opener(_NoRedirect).open(req, timeout=5)
        hdrs, body, st = dict(r.headers), r.read().decode("utf-8", "replace"), r.status
    except urllib.error.HTTPError as e:
        hdrs, body, st = dict(e.headers), e.read().decode("utf-8", "replace"), e.code
    return st, {k.lower(): v for k, v in hdrs.items()}.get("location"), body


class _Edge:
    """A running hermetic edge over one fixture route table."""

    def __init__(self, td: Path, mappath: Path, text: str | None = None):
        self.td, self.stub_port, self.port = td, _free_port(), _free_port()
        self.stub = _run_caddy(_stub_cfg(self.stub_port), td, f"stub-{self.port}")
        cfg = _hermetic(text or _fd_text(), td, self.port, self.stub_port, mappath)
        self.fd = _run_caddy(cfg, td, f"frontdoor-{self.port}")
        _wait_port(self.stub_port)
        _wait_port(self.port)

    def get(self, path: str, host: str = "canonical.test"):
        return _get(self.port, path, host)

    def stop(self):
        _stop(self.fd)
        _stop(self.stub)


