@pytest.mark.skipif(not _HAS_CADDY, reason="no caddy binary on PATH - runtime pins run in CI (gateway-ci)")
def test_runtime_a_query_never_reaches_the_location(gated):
    """RUNTIME, the open-redirect refusal. The map keys off the QUERY-STRIPPED remainder, so a
    decorated link resolves to the same clean NCI Location and an attacker-supplied `?u=` cannot ride
    onto it or replace it. SENSITIVITY CONTROL: the request still 302s (the query is dropped from the
    TARGET, not treated as an unknown route), and the undecorated path gives the identical Location.
    FAILS IF any query byte appears in the Location."""
    clean = gated.get("/go/ts/open-survey/OPEN1/raw_packed")[1]
    for query in ("?u=https://evil.example", "?utm=1&v=2", "?u=https%3A%2F%2Fevil.example"):
        st, loc, _ = gated.get(f"/go/ts/open-survey/OPEN1/raw_packed{query}")
        assert st == 302, f"{query}: the route must still resolve, got {st}"
        assert loc == clean, f"{query}: the query must not reach the Location, got {loc!r}"
        assert "evil.example" not in (loc or "") and "?" not in (loc or "")
    st, loc, _ = gated.get("/go/ts/held-survey/HELD1/raw_packed?u=https://evil.example")
    assert st == 404 and loc is None, "a query cannot resurrect a suppressed route either"


